from pathlib import Path
import json,subprocess,unittest
ROOT=Path(__file__).resolve().parents[2]
class SourceDiagnostic(unittest.TestCase):
 def php(self,code):
  p=subprocess.run(['php','-r',code,str(ROOT)],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');return json.loads(p.stdout)
 def test_component_projection_never_exports_private_values_or_unknown_keys(self):
  d=self.php(r'''require $argv[1].'/support/governance/recovery/partial-source-diagnostic.php';$before=['partial_facts'=>['application-config'=>['source_digest'=>'SECRET_OLD']],'credentials'=>['password'=>'SECRET_OLD']];$after=$before;$after['partial_facts']['application-config']['source_digest']='SECRET_NEW';$after['credentials']['password']='SECRET_NEW';$after['unknown']='SECRET_UNKNOWN';$value=['schema'=>'native-partial-source-difference-v1','reader_succeeded'=>true,'fixture_policy_row_absent'=>true,'approval_fingerprint_unchanged'=>true,'changed'=>governance_recovery_partial_source_components($before,$after),'raw'=>'SECRET_PAYLOAD'];$positive=governance_recovery_partial_source_projection($value);$negative=[];foreach(['missing','extra','type','schema','status']as$case){$bad=$value;if($case==='missing')unset($bad['changed']['policy']);if($case==='extra')$bad['changed']['SECRET_KEY']=true;if($case==='type')$bad['changed']['policy']=1;if($case==='schema')$bad['schema']='secret';if($case==='status')$bad['reader_succeeded']=false;$negative[]=governance_recovery_partial_source_projection($bad);}echo json_encode(['positive'=>$positive,'negative'=>$negative]);''')
  self.assertNotIn('SECRET',json.dumps(d));v=d['positive'];self.assertEqual(len(v['changed']),13);self.assertTrue(v['changed']['application-config']);self.assertTrue(v['changed']['credentials']);self.assertTrue(v['changed']['other-bound-fields']);self.assertFalse(v['changed']['policy']);self.assertEqual(d['negative'],[{'schema':'native-partial-source-difference-v1','reader_succeeded':False}]*5)
